import{_ as t,o as a,c as r,ao as o}from"./chunks/framework.Bre6m-jb.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md","lastUpdated":null}'),i={name:"changelog.md"};function n(l,e,d,c,u,s){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="Changelog" tabindex="-1">Changelog <a class="header-anchor" href="#Changelog" aria-label="Permalink to &quot;Changelog {#Changelog}&quot;">​</a></h1><p>All notable changes to this project will be documented in this file.</p><p>The format is based on <a href="https://keepachangelog.com/en/1.1.0/" target="_blank" rel="noreferrer">Keep a Changelog</a>, and this project adheres to <a href="https://semver.org/spec/v2.0.0.html" target="_blank" rel="noreferrer">Semantic Versioning</a>.</p><h2 id="Guidelines-for-updating-this-changelog" tabindex="-1">Guidelines for updating this changelog <a class="header-anchor" href="#Guidelines-for-updating-this-changelog" aria-label="Permalink to &quot;Guidelines for updating this changelog {#Guidelines-for-updating-this-changelog}&quot;">​</a></h2><p>When making changes to this project, please update the &quot;Unreleased&quot; section with your changes under the appropriate category:</p><ul><li><p><strong>Added</strong> for new features.</p></li><li><p><strong>Changed</strong> for changes in existing functionality.</p></li><li><p><strong>Deprecated</strong> for soon-to-be removed features.</p></li><li><p><strong>Removed</strong> for now removed features.</p></li><li><p><strong>Fixed</strong> for any bug fixes.</p></li></ul><p>When releasing a new version, move the &quot;Unreleased&quot; changes to a new version section with the release date.</p><h2 id="Unreleasedhttps://github.com/QuantumKitHub/MPSKit.jl/compare/v0.14.0...HEAD" tabindex="-1"><a href="https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.14.0...HEAD" target="_blank" rel="noreferrer">Unreleased</a> <a class="header-anchor" href="#Unreleasedhttps://github.com/QuantumKitHub/MPSKit.jl/compare/v0.14.0...HEAD" aria-label="Permalink to &quot;[Unreleased](https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.14.0...HEAD) {#Unreleasedhttps://github.com/QuantumKitHub/MPSKit.jl/compare/v0.14.0...HEAD}&quot;">​</a></h2><h3 id="Added" tabindex="-1">Added <a class="header-anchor" href="#Added" aria-label="Permalink to &quot;Added {#Added}&quot;">​</a></h3><h3 id="Changed" tabindex="-1">Changed <a class="header-anchor" href="#Changed" aria-label="Permalink to &quot;Changed {#Changed}&quot;">​</a></h3><h3 id="Deprecated" tabindex="-1">Deprecated <a class="header-anchor" href="#Deprecated" aria-label="Permalink to &quot;Deprecated {#Deprecated}&quot;">​</a></h3><h3 id="Removed" tabindex="-1">Removed <a class="header-anchor" href="#Removed" aria-label="Permalink to &quot;Removed {#Removed}&quot;">​</a></h3><h3 id="Fixed" tabindex="-1">Fixed <a class="header-anchor" href="#Fixed" aria-label="Permalink to &quot;Fixed {#Fixed}&quot;">​</a></h3><h3 id="Performance" tabindex="-1">Performance <a class="header-anchor" href="#Performance" aria-label="Permalink to &quot;Performance {#Performance}&quot;">​</a></h3><h2 id="0.14.0https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.13...v0.14.0-2026-10-05" tabindex="-1"><a href="https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.13...v0.14.0" target="_blank" rel="noreferrer">0.14.0</a> - 2026-10-05 <a class="header-anchor" href="#0.14.0https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.13...v0.14.0-2026-10-05" aria-label="Permalink to &quot;[0.14.0](https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.13...v0.14.0) - 2026-10-05 {#0.14.0https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.13...v0.14.0-2026-10-05}&quot;">​</a></h2><h3 id="Added-2" tabindex="-1">Added <a class="header-anchor" href="#Added-2" aria-label="Permalink to &quot;Added {#Added-2}&quot;">​</a></h3><ul><li><p><code>WindowMPOHamiltonian</code>, enabling propagators and dynamical DMRG on <code>WindowMPS</code>. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/417" target="_blank" rel="noreferrer">#417</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/447" target="_blank" rel="noreferrer">#447</a>)</p></li><li><p><code>SketchedExpand</code> for randomized controlled bond expansion in DMRG and TDVP. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/438" target="_blank" rel="noreferrer">#438</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/464" target="_blank" rel="noreferrer">#464</a>)</p></li><li><p><code>DMRG3S</code> for single-site DMRG with subspace expansion and configurable noise schedules. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/460" target="_blank" rel="noreferrer">#460</a>)</p></li><li><p><code>leftunit</code>/<code>rightunit</code> for <code>MultilineMPS</code> and <code>MultilineMPO</code>. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/453" target="_blank" rel="noreferrer">#453</a>)</p></li><li><p>Controlled bond expansion for finite single-site <code>DMRG</code> and <code>TDVP</code> via <code>alg_expand</code>, with configurable QR/SVD gauging through <code>alg_svd</code>, <code>alg_orth</code>, and <code>trunc</code>. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/438" target="_blank" rel="noreferrer">#438</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/460" target="_blank" rel="noreferrer">#460</a>)</p></li><li><p><code>changebond</code>/<code>changebond!</code> for expanding a single finite-MPS bond in a chosen sweep direction. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/438" target="_blank" rel="noreferrer">#438</a>)</p></li><li><p>A keyword-based <code>approximate(ψ₀, (O, ψ); tol, maxiter, verbosity, trunc)</code> convenience method and sequential approximation algorithms composed with <code>&amp;</code>. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/469" target="_blank" rel="noreferrer">#469</a>)</p></li><li><p><code>Adapt</code> support for <code>Multiline</code> and <code>PeriodicArray</code> objects, including multiline MPS/MPO networks. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/406" target="_blank" rel="noreferrer">#406</a>)</p></li><li><p>Custom <code>hasconverged</code> and <code>shouldstop</code> callbacks on <code>GradientGrassmann</code>. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/510" target="_blank" rel="noreferrer">#510</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/512" target="_blank" rel="noreferrer">#512</a>)</p></li><li><p><code>DynamicTols.adapt_solver</code> and <code>AdaptiveKrylov</code> for adapting eigensolver tolerances and Krylov budgets to local gradients and truncation errors. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/455" target="_blank" rel="noreferrer">#455</a>)</p></li><li><p>Addition of <code>FiniteMPS</code>/<code>FiniteMPO</code> with different scalar types, through a new <code>Base.similar(ψ, ::Type{S})</code> for <code>S &lt;: Number</code> on <code>FiniteMPS</code>. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/484" target="_blank" rel="noreferrer">#484</a>)</p></li><li><p><code>Zipup</code>, an algorithm for <code>approximate</code>/<code>approximate!</code> that compresses a finite MPO-MPS product in a single sweep, optionally followed by a sweep in the opposite direction that imposes the final truncation. The sweep direction is selected by the <code>left_to_right</code> keyword. Both <code>approximate((O, ϕ), alg)</code> and <code>approximate!(ψ, (O, ϕ), alg)</code> are supported, where the destination <code>ψ</code> is a write target rather than an initial guess and may alias <code>ϕ</code>; they return <code>(ψ, info)</code>. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/470" target="_blank" rel="noreferrer">#470</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/513" target="_blank" rel="noreferrer">#513</a>)</p></li><li><p><code>BUG</code> time-evolution algorithm: a Basis-Update &amp; Galerkin integrator for finite MPS. Unlike <code>TDVP</code> it has no backward-in-time substep (stable for imaginary-time evolution), and passing a truncating <code>trunc</code> enables rank-adaptivity (the bond dimension grows and shrinks automatically to track entanglement). (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/468" target="_blank" rel="noreferrer">#468</a>)</p></li><li><p>A <code>backend</code> setting on every algorithm, for its tensor contractions and index manipulations, defaulting to <code>MPSKit.Defaults.backend()</code>. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/467" target="_blank" rel="noreferrer">#467</a>)</p></li><li><p>Local updates now serve their intermediate tensors from a dedicated allocator, selected internally by <code>MPSKit.default_allocator</code>, instead of leaving them to the garbage collector (two-site DMRG: -64% allocations, -57% GC time, -23% wall time). Disable with <code>MPSKit.Defaults.set_buffering!(false)</code>. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/467" target="_blank" rel="noreferrer">#467</a>)</p></li><li><p>Custom <code>show</code>/<code>summary</code> for <code>MultilineMPS</code>/<code>MultilineMPO</code>. Each row is now rendered via each row&#39;s own display, and row shifting is shown explicitly for <code>MultilineMPO</code>. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/508" target="_blank" rel="noreferrer">#508</a>)</p></li><li><p><code>*(::MultilineMPO, ::InfiniteMPS)</code>, which pushes the boundary MPS through every row of the network in turn, advancing it by one full period. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/508" target="_blank" rel="noreferrer">#508</a>)</p></li><li><p><code>leading_eigenvalue(ψ, O, [environments])</code>, the eigenvalue of the transfer operator <code>O</code> for the boundary MPS <code>ψ</code>, i.e. the partition function density. <code>expectation_value(::InfiniteMPS, ::InfiniteMPO)</code> forwards here. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/508" target="_blank" rel="noreferrer">#508</a>)</p></li><li><p><code>InfiniteMultilineMPS</code>/<code>FiniteMultilineMPS</code> and <code>InfiniteMultilineMPO</code>/<code>FiniteMultilineMPO</code> aliases for multiline objects with infinite or finite lines. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/508" target="_blank" rel="noreferrer">#508</a>)</p></li></ul><h3 id="Changed-2" tabindex="-1">Changed <a class="header-anchor" href="#Changed-2" aria-label="Permalink to &quot;Changed {#Changed-2}&quot;">​</a></h3><ul><li><p>Algorithm logging now uses named initialization, iteration, convergence, and non-convergence groups, replacing the deprecated LoggingExtras verbosity APIs. LoggingExtras 1.1 and 1.2 are supported alongside 1.0. Canonicalization now logs initialization at verbosity 2 and non-convergence warnings at verbosity 1, consistently with the other algorithms.</p></li><li><p><code>DMRG</code>/<code>DMRG2</code> use Galerkin error for convergence and <code>AdaptiveKrylov</code> for adaptive local eigensolvers; truncating runs can converge once the Galerkin error reaches the truncation-error floor. <code>FiniteExcited</code> perturbs its default initial guess to avoid starting at an already-converged eigenstate. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/455" target="_blank" rel="noreferrer">#455</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/512" target="_blank" rel="noreferrer">#512</a>)</p></li><li><p><code>JordanMPOTensor</code> now stores non-identity blocks and scalar identity contributions separately, with revised type parameters and constructors. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/444" target="_blank" rel="noreferrer">#444</a>)</p></li><li><p>Dependency compatibility now includes OptimKit 0.5 and VectorInterface 0.7; OptimKit 0.3 is no longer supported. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/456" target="_blank" rel="noreferrer">#456</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/460" target="_blank" rel="noreferrer">#460</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/530" target="_blank" rel="noreferrer">#530</a>)</p></li><li><p>Environment solver settings are forwarded more consistently through VUMPS/VOMPS, lazy sums, and quasiparticle calculations; gauge updates honor the configured orthogonalization algorithm. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/436" target="_blank" rel="noreferrer">#436</a>)</p></li><li><p>Hamiltonian matrix constructors accept <code>AbstractMatrix</code> entries, and <code>similar</code> for MPOs and MPO Hamiltonians also accepts a storage type. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/406" target="_blank" rel="noreferrer">#406</a>)</p></li><li><p>Raised minimum TensorKit and TensorOperations versions to 0.17.1 and 5.6.2, respectively. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/444" target="_blank" rel="noreferrer">#444</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/467" target="_blank" rel="noreferrer">#467</a>)</p></li><li><p><code>FiniteMPOHamiltonian</code>/<code>InfiniteMPOHamiltonian</code> constructed from a set of local terms now share virtual channels between terms that start out with the same operators, up to a scalar factor, and add up terms that are linearly dependent. The resulting Hamiltonian is unchanged, but its bond dimension is generally smaller (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/518" target="_blank" rel="noreferrer">#518</a>)</p></li><li><p><code>find_groundstate(!)</code>, <code>leading_boundary</code>, <code>approximate(!)</code>, <code>timestep(!)</code> and <code>time_evolve(!)</code> now return diagnostics through <code>AlgorithmInfo</code> (normally <code>(ψ, envs, info)</code>; <code>Zipup</code> returns <code>(ψ, info)</code>). The <code>info</code> object contains diagnostics about the run and convergence. See the updated docs or <code>AlgorithmInfo</code>&#39;s docstring for more information. <code>convergence_measure(info)</code> extracts the algorithm-specific stopping measure. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/512" target="_blank" rel="noreferrer">#512</a>)</p></li><li><p>The manual has a new section on <a href="/MPSKit.jl/dev/man/algorithms#Errors-and-accuracy">Errors and accuracy</a> covering definitions and interpretations of the various returned measures. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/512" target="_blank" rel="noreferrer">#512</a>)</p></li><li><p>Convergence tolerances are now compared with <code>&lt;=</code> everywhere, so an error exactly equal to <code>tol</code> counts as converged for <code>DMRG</code>/<code>DMRG2</code> in <code>approximate</code>, the <code>IDMRG</code>/<code>IDMRG2</code> variants of <code>approximate</code> and <code>leading_boundary</code>, and the gauge fixing of <code>InfiniteMPS</code>, as it already did for the other algorithms. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/512" target="_blank" rel="noreferrer">#512</a>)</p></li><li><p>Renormalization during time evolution is now controlled by an explicit <code>normalize</code> keyword on <code>timestep</code>/<code>time_evolve</code> (default <code>false</code>), decoupled from <code>imaginary_evolution</code>. By default the norm is preserved, so it retains useful information (the accumulated truncation error in real time, or the decaying weight in imaginary time). Previously imaginary-time evolution always renormalized every step; <strong>to recover that behavior, pass <code>normalize = true</code></strong> (e.g. for ground-state or thermal-state search via imaginary-time evolution). (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/438" target="_blank" rel="noreferrer">#438</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/469" target="_blank" rel="noreferrer">#469</a>)</p></li><li><p><code>environments</code> now follows a single positional contract for every state and operator kind: <code>environments(below, operator, above, alg)</code>, where <code>alg</code> is the environment algorithm (slot 4). The operator form requires an explicit <code>above</code>. Auxiliary inputs are keyword-only: <code>leftstart</code>/<code>rightstart</code> for finite and window environments, and <code>lenvs</code>/<code>renvs</code> for window and quasiparticle environments. The two-argument form <code>environments(below, above)</code> (with two states) is reserved for the operator-free overlap environments. There is no two-argument <code>environments(below, operator)</code> shorthand: a two-argument call is always the overlap, since the second argument cannot be disambiguated between a ket and an operator (undecidable for density matrices, where states and operators share a representation). (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/436" target="_blank" rel="noreferrer">#436</a>)</p></li><li><p><code>transfer_spectrum</code> now computes the spectrum for all sectors of the transfer space at once, returning a <code>TensorKit.SectorVector</code> that can be indexed per sector. The <code>sector</code> keyword is removed; a specific selection of sectors (with per-sector counts) can be requested by passing <code>howmany</code> as an <code>AbstractDict</code>/iterable of <code>sector =&gt; count</code> pairs. The <code>below</code> state and the eigensolver algorithm are optional positional arguments, and the algorithm can be resolved per sector. The Krylov dimension adapts to the number of values requested in each sector, controlled by the new <code>oversampling</code> and <code>oversampling_factor</code> keywords. Accordingly, <code>marek_gap</code> and <code>correlation_length</code> now return a <code>TensorKit.SectorDict</code> of per-sector results by default; pass <code>sector = ...</code> to obtain a single sector&#39;s result as before. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/452" target="_blank" rel="noreferrer">#452</a>)</p></li><li><p>All <code>trscheme</code> keyword arguments are renamed to <code>trunc</code> (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/482" target="_blank" rel="noreferrer">#482</a>).</p></li><li><p><code>correlator</code> now throws an <code>ArgumentError</code> when the sites are not ordered as <code>i &lt; j</code>. Previously such a call only logged an <code>@error</code> and then continued into a contraction that is not the requested correlator. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/489" target="_blank" rel="noreferrer">#489</a>)</p></li><li><p>TimerOutputs 1.x is now required. The timing tables printed at <code>verbosity &gt; 3</code> use the new layout (tree guides, heat bars) and additionally report per-section GC time. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/495" target="_blank" rel="noreferrer">#495</a>)</p></li><li><p><code>Multiline</code> (and therefore <code>MultilineMPS</code>/<code>MultilineMPO</code>) now consistently behaves as a vector of the lines it stores: <code>length</code>/<code>size</code>/<code>axes</code>/<code>eachindex</code>/<code>eltype</code>/<code>iterate</code>/<code>m[i]</code> all refer to the lines, so <code>size(m) == (length(m),)</code>. Previously <code>length</code> counted <code>nrows * ncols</code> and <code>size</code> returned the <code>(nrows, ncols)</code> lattice shape. The <code>AL</code>/<code>AR</code>/<code>AC</code>/<code>C</code> views still index the lattice as <code>[row, col]</code>. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/508" target="_blank" rel="noreferrer">#508</a>)</p></li><li><p><code>MultilineMPS</code> lines may now be any <code>AbstractMPS</code> rather than only <code>InfiniteMPS</code>, so that for example finite multiline networks can be built and inspected. No algorithm supports them yet: <code>leading_boundary</code> only accepts an <code>InfiniteMultilineMPS</code> (and an <code>InfiniteMultilineMPO</code>). The <code>AbstractMatrix</code> constructor that silently built finite-line <code>MultilineMPO</code>s was removed. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/508" target="_blank" rel="noreferrer">#508</a>)</p></li></ul><h3 id="Deprecated-2" tabindex="-1">Deprecated <a class="header-anchor" href="#Deprecated-2" aria-label="Permalink to &quot;Deprecated {#Deprecated-2}&quot;">​</a></h3><ul><li><code>DynamicTols.updatetol(alg, iter, ϵ)</code>; use <code>DynamicTols.adapt_solver(alg; iter, g_global = ϵ)</code> instead. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/455" target="_blank" rel="noreferrer">#455</a>)</li></ul><h3 id="Removed-2" tabindex="-1">Removed <a class="header-anchor" href="#Removed-2" aria-label="Permalink to &quot;Removed {#Removed-2}&quot;">​</a></h3><ul><li><p>The custom <code>MPSTensor</code> constructors; construct <code>TensorMap</code>s with explicit <code>TensorMapSpace</code>s instead. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/475" target="_blank" rel="noreferrer">#475</a>)</p></li><li><p><code>JordanMPOTensorMap</code>; use <code>JordanMPOTensor</code> instead. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/444" target="_blank" rel="noreferrer">#444</a>)</p></li><li><p>Support for TimerOutputs 0.5. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/495" target="_blank" rel="noreferrer">#495</a>)</p></li><li><p><code>expectation_value</code> for a <code>MultilineMPS</code>/<code>MultilineMPO</code> pair entirely, replaced by <code>leading_eigenvalue</code>. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/508" target="_blank" rel="noreferrer">#508</a>)</p></li><li><p><code>*(::MultilineMPO, ::MultilineMPS)</code> and <code>*(::MultilineMPO, ::MultilineMPO)</code>, as these were not meaningful operations. Neither method had ever been callable previously. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/508" target="_blank" rel="noreferrer">#508</a>)</p></li></ul><h3 id="Fixed-2" tabindex="-1">Fixed <a class="header-anchor" href="#Fixed-2" aria-label="Permalink to &quot;Fixed {#Fixed-2}&quot;">​</a></h3><ul><li><p><code>entropy</code>, <code>entanglement_spectrum</code>, and <code>entanglementplot</code> now accept the left boundary (<code>site = 0</code>) of a finite MPS; the plot uses the selected bond to label its dimension. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/504" target="_blank" rel="noreferrer">#504</a>)</p></li><li><p><code>GradientGrassmann</code> preconditioning could cease to be a descent direction on nearly rank-deficient bonds; the regularized inverse is now applied in factored form. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/532" target="_blank" rel="noreferrer">#532</a>)</p></li><li><p><code>variance</code> and Hamiltonian arithmetic now support mixed scalar types; finite-state variance is evaluated using the energy-shifted Hamiltonian to reduce cancellation. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/529" target="_blank" rel="noreferrer">#529</a>)</p></li><li><p><code>canonicalize!</code> no longer raises a <code>SpaceMismatch</code> for partially decoupled Hamiltonian sites. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/526" target="_blank" rel="noreferrer">#526</a>)</p></li><li><p>Infinite-MPO quasiparticle environments now use the correct bond indices when virtual spaces vary within the unit cell. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/492" target="_blank" rel="noreferrer">#492</a>)</p></li><li><p><code>remove_orphans!</code> now terminates correctly when infinite-MPO virtual channels stop changing. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/485" target="_blank" rel="noreferrer">#485</a>)</p></li><li><p><code>periodic_boundary_conditions</code> no longer raises a <code>SpaceMismatch</code> for non-self-dual virtual spaces. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/462" target="_blank" rel="noreferrer">#462</a>)</p></li><li><p><code>FiniteExcited</code> returns excitations in ascending energy order. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/443" target="_blank" rel="noreferrer">#443</a>)</p></li><li><p>Precomputed bond derivatives now allocate contractions consistently with TensorKit multifusion space checks. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/528" target="_blank" rel="noreferrer">#528</a>)</p></li><li><p><code>time_evolve</code> logging no longer references an undefined time or passes integer placeholders to floating-point logging methods. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/469" target="_blank" rel="noreferrer">#469</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/515" target="_blank" rel="noreferrer">#515</a>)</p></li><li><p>MPO multiplication, physical-charge insertion, and Jordan-tensor scalar conversion preserve GPU storage instead of constructing CPU intermediates. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/406" target="_blank" rel="noreferrer">#406</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/444" target="_blank" rel="noreferrer">#444</a>)</p></li><li><p><code>changebonds(::FiniteMPO, ::SvdCut)</code> truncated long chains down to a zero operator. It now gauges in a separate sweep, spreads the operator norm evenly over the sites, and truncates against the per-bond reference scale <code>‖O‖^(2/length(mpo))</code>. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/519" target="_blank" rel="noreferrer">#519</a>)</p></li><li><p><code>changebonds(::FiniteMPOHamiltonian, ::SvdCut)</code> threw a <code>BoundsError</code> for Hamiltonians with long-range terms. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/519" target="_blank" rel="noreferrer">#519</a>)</p></li><li><p><code>SvdCut</code> now warns when a truncation empties a bond, instead of silently returning a zero operator. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/519" target="_blank" rel="noreferrer">#519</a>)</p></li><li><p><code>checkbounds</code> on the <code>AL</code>/<code>AR</code>/<code>AC</code>/<code>C</code> views of a <code>Multiline</code> now delegates the column to the matching tensors of a line, and accepts any row due to periodicity. <code>checkbounds(Bool, ::PeriodicArray, I...)</code> now also accepts any index, matching <code>getindex</code>. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/508" target="_blank" rel="noreferrer">#508</a>)</p></li><li><p><code>size</code>/<code>axes</code> for a <code>CView</code> over a <code>Multiline</code> with finite lines were missing. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/508" target="_blank" rel="noreferrer">#508</a>)</p></li><li><p><code>excitations(::InfiniteMPO, ::QuasiparticleAnsatz, ::InfiniteQP, lenvs, renvs)</code> referenced <code>H_eff</code> before assigning. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/489" target="_blank" rel="noreferrer">#489</a>)</p></li><li><p><code>Base.:+</code>/<code>-</code> on <code>FiniteMPS</code> returned a wrong state for near-parallel operands carried by different tensor networks, e.g. <code>norm(E₀ * gs - H * gs)</code> coming out as <code>2 * norm(gs) * E₀</code> instead of ~0. The lazy gauge sweep in <code>CView.getindex</code> re-derived <code>AL</code>/<code>C</code> entries that were already cached, and since different code paths install different factorizations (a truncated SVD from DMRG vs. a positive QR from the sweep) the replacement differed by a bond unitary, so <code>+</code> combined tensors belonging to two different gauges. The same staleness was latent in every consumer that reads several gauge tensors across a center move, <code>dot</code> included. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/issues/473" target="_blank" rel="noreferrer">#473</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/484" target="_blank" rel="noreferrer">#484</a>)</p></li><li><p>Addition of single-site operands. <code>FiniteMPS + FiniteMPS</code> asserted <code>length &gt; 1</code>, and <code>FiniteMPO + FiniteMPO</code> threw a space error, because both split the chain into a left and a right block and fuse them at the seam — of which there is none at length 1. Such an operand has no internal bond to fuse, so the sum is now simply the sum of the two tensors. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/484" target="_blank" rel="noreferrer">#484</a>)</p></li><li><p><code>convert(TensorMap, ::FiniteMPO)</code> on a single-site MPO stripped the left virtual leg of <code>mpo[1]</code> and the right virtual leg of <code>mpo[end]</code> and contracted the two — which at length 1 is the <em>same</em> tensor, so it returned <code>O * O</code> on twice the physical space instead of <code>O</code>. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/484" target="_blank" rel="noreferrer">#484</a>)</p></li><li><p><code>leading_boundary</code> with <code>IDMRG2</code> didn&#39;t update the left edge of the AC tensor, which could result in space mismatches depending on the truncation scheme. This is corrected for in (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/516" target="_blank" rel="noreferrer">#516</a>).</p></li><li><p>Fix hardcoding of number of physical spaces in the <code>changebonds</code> implementations for <code>FiniteMPS</code>, enabling its use for systems with composite physical spaces (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/514" target="_blank" rel="noreferrer">#514</a>)</p></li><li><p>Fix density matrix methods with anyonic symmetries through consistency of braid orientation. This affected <code>approximate</code>, <code>DMRG2</code>, and <code>timestep</code> on density matrices for anyonic sector types. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/509" target="_blank" rel="noreferrer">#509</a>)</p></li><li><p><code>_mpo_to_mps</code> threw a <code>SpaceMismatch</code> when converting a block/Jordan-structured MPO tensor (e.g. from <code>make_time_mpo</code>) into an MPS, since it braided the physical leg directly against a <code>SumSpace</code> virtual leg. It now densifies the tensor first, which the function already did to its return value regardless, so this adds no extra cost. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/509" target="_blank" rel="noreferrer">#509</a>)</p></li><li><p><code>make_time_mpo</code> with <code>TaylorCluster</code> on a Hamiltonian whose virtual bond dimension varies along the chain are now correctly handled. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/511" target="_blank" rel="noreferrer">#511</a>)</p></li><li><p>The converting constructor of <code>JordanMPO_AC_Hamiltonian</code> assigned the &quot;finished&quot; block <code>E</code> to the &quot;ending&quot; field <code>B</code> whenever <code>B</code> was absent, raising a <code>convert</code> <code>MethodError</code> from deep inside <code>AC_hamiltonian</code>. This is reached when an <code>MPOHamiltonian</code> whose scalartype differs from the state&#39;s has an on-site term on a site where no interaction ends, such as a long-range one. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/493" target="_blank" rel="noreferrer">#493</a>)</p></li><li><p>Raised the <code>BlockTensorKit</code> compat lower bound to 0.3.19, which fixes a silent data-loss bug: with <code>TensorKit</code> 0.17.2 and <code>BlockTensorKit</code> &lt;= 0.3.18, a permuted contraction into a sparse block tensor (e.g. an environment sweep near a <code>FiniteMPS</code> chain boundary when the operator and state have different <code>scalartype</code>s) could silently drop data instead of erroring. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/493" target="_blank" rel="noreferrer">#493</a>)</p></li><li><p><code>approximate</code> with <code>IDMRG2</code> on a <code>MultilineMPS</code> with more than one row wrote the right-to-left edge update into the wrong row and refreshed the unit cell edge of the first row only, so the rows ended up mixed. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/512" target="_blank" rel="noreferrer">#512</a>)</p></li><li><p><code>leading_boundary</code> with <code>GradientGrassmann</code> ignored the algorithm&#39;s <code>hasconverged</code> and <code>shouldstop</code> criteria, always using the optimizer&#39;s defaults instead. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/512" target="_blank" rel="noreferrer">#512</a>)</p></li><li><p><code>isfinite(::MultilineMPO)</code> threw (<code>isfinite(typeof(m))</code> had no matching type-level method for <code>Multiline</code>). (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/508" target="_blank" rel="noreferrer">#508</a>)</p></li><li><p><code>changebonds(::MultilineMPO, ::SvdCut)</code> threw (<code>convert(MultilineMPS, ::MultilineMPO)</code> has no method). (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/508" target="_blank" rel="noreferrer">#508</a>)</p></li><li><p><code>axes(m::Multiline, i)</code> threw for <code>i &gt; 2</code>, but now returns <code>Base.OneTo(1)</code> for every trailing dimension, matching Base&#39;s own convention. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/508" target="_blank" rel="noreferrer">#508</a>)</p></li></ul><h3 id="Performance-2" tabindex="-1">Performance <a class="header-anchor" href="#Performance-2" aria-label="Permalink to &quot;Performance {#Performance-2}&quot;">​</a></h3><ul><li><p><code>dot</code> on identical <code>FiniteMPS</code> objects uses a norm-based shortcut, also avoiding redundant contractions in expectation values. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/491" target="_blank" rel="noreferrer">#491</a>)</p></li><li><p>Improved two-site effective-Hamiltonian contractions for long-range interactions. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/505" target="_blank" rel="noreferrer">#505</a>)</p></li><li><p>Extended scratch-allocator use to additional derivative contractions and TDVP bond updates. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/520" target="_blank" rel="noreferrer">#520</a>)</p></li><li><p>Reorganised the test suite to reduce CI wall time, as well as added the <code>--fast</code> test flag to test fewer sector and scalar types. (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/517" target="_blank" rel="noreferrer">#517</a>)</p></li><li><p><code>TDVP2</code> now performs its two-site split through the shared <code>gauge2!</code> (as two-site DMRG already did), avoiding unnecessary re-orthogonalisation and complexification where applicable). (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/517" target="_blank" rel="noreferrer">#517</a>)</p></li></ul><h2 id="0.13.11https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.10...v0.13.11-2026-05-04" tabindex="-1"><a href="https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.10...v0.13.11" target="_blank" rel="noreferrer">0.13.11</a> - 2026-05-04 <a class="header-anchor" href="#0.13.11https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.10...v0.13.11-2026-05-04" aria-label="Permalink to &quot;[0.13.11](https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.10...v0.13.11) - 2026-05-04 {#0.13.11https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.10...v0.13.11-2026-05-04}&quot;">​</a></h2><h3 id="Added-3" tabindex="-1">Added <a class="header-anchor" href="#Added-3" aria-label="Permalink to &quot;Added {#Added-3}&quot;">​</a></h3><ul><li><code>MultilineMPO</code> space getters (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/407" target="_blank" rel="noreferrer">#407</a>)</li></ul><h3 id="Changed-3" tabindex="-1">Changed <a class="header-anchor" href="#Changed-3" aria-label="Permalink to &quot;Changed {#Changed-3}&quot;">​</a></h3><ul><li><p>Refactored time-evolution MPO construction (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/422" target="_blank" rel="noreferrer">#422</a>)</p></li><li><p>Updated <code>TensorKitManifolds</code> compat to 0.8 (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/421" target="_blank" rel="noreferrer">#421</a>)</p></li><li><p>Updated MatrixAlgebraKit algorithm specification (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/418" target="_blank" rel="noreferrer">#418</a>)</p></li><li><p>Preparations for GPU / non-CPU array support (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/375" target="_blank" rel="noreferrer">#375</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/392" target="_blank" rel="noreferrer">#392</a>)</p></li><li><p>Generalized <code>calc_galerkin</code> to <code>AbstractMPS</code> (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/395" target="_blank" rel="noreferrer">#395</a>)</p></li><li><p>Removed explicit call to <code>InfiniteMPS</code> in VUMPS (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/396" target="_blank" rel="noreferrer">#396</a>)</p></li><li><p>Generalized <code>regauge!</code> to <code>AbstractVector</code> (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/393" target="_blank" rel="noreferrer">#393</a>)</p></li></ul><h3 id="Fixed-3" tabindex="-1">Fixed <a class="header-anchor" href="#Fixed-3" aria-label="Permalink to &quot;Fixed {#Fixed-3}&quot;">​</a></h3><ul><li><p>Various fixes for compatibility with latest TensorKit versions (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/416" target="_blank" rel="noreferrer">#416</a>)</p></li><li><p><code>changebonds</code> inconsistencies (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/415" target="_blank" rel="noreferrer">#415</a>)</p></li><li><p>Small fixes for density operators (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/409" target="_blank" rel="noreferrer">#409</a>)</p></li><li><p>Tolerance on positivity test (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/398" target="_blank" rel="noreferrer">#398</a>)</p></li></ul><h3 id="Performance-3" tabindex="-1">Performance <a class="header-anchor" href="#Performance-3" aria-label="Permalink to &quot;Performance {#Performance-3}&quot;">​</a></h3><ul><li>Benchmarks and AC/AC2 contraction improvements (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/345" target="_blank" rel="noreferrer">#345</a>)</li></ul><h2 id="0.13.10https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.9...v0.13.10-2026-02-26" tabindex="-1"><a href="https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.9...v0.13.10" target="_blank" rel="noreferrer">0.13.10</a> - 2026-02-26 <a class="header-anchor" href="#0.13.10https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.9...v0.13.10-2026-02-26" aria-label="Permalink to &quot;[0.13.10](https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.9...v0.13.10) - 2026-02-26 {#0.13.10https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.9...v0.13.10-2026-02-26}&quot;">​</a></h2><h3 id="Added-4" tabindex="-1">Added <a class="header-anchor" href="#Added-4" aria-label="Permalink to &quot;Added {#Added-4}&quot;">​</a></h3><ul><li><p><code>expectation_value</code> for local MPO tensors (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/327" target="_blank" rel="noreferrer">#327</a>)</p></li><li><p><code>Base.copy</code> for MPS types now performs a deep copy (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/387" target="_blank" rel="noreferrer">#387</a>)</p></li></ul><h3 id="Changed-4" tabindex="-1">Changed <a class="header-anchor" href="#Changed-4" aria-label="Permalink to &quot;Changed {#Changed-4}&quot;">​</a></h3><ul><li><p><code>entropy</code> can now also be called directly on a spectrum (singular value vector) (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/377" target="_blank" rel="noreferrer">#377</a>)</p></li><li><p>Updated compat bounds to remove broken package versions</p></li></ul><h3 id="Fixed-4" tabindex="-1">Fixed <a class="header-anchor" href="#Fixed-4" aria-label="Permalink to &quot;Fixed {#Fixed-4}&quot;">​</a></h3><ul><li>Fixed <code>Adapt</code> extension for GPU support (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/389" target="_blank" rel="noreferrer">#389</a>)</li></ul><h2 id="0.13.9https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.8...v0.13.9-2026-02-03" tabindex="-1"><a href="https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.8...v0.13.9" target="_blank" rel="noreferrer">0.13.9</a> - 2026-02-03 <a class="header-anchor" href="#0.13.9https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.8...v0.13.9-2026-02-03" aria-label="Permalink to &quot;[0.13.9](https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.8...v0.13.9) - 2026-02-03 {#0.13.9https://github.com/QuantumKitHub/MPSKit.jl/compare/v0.13.8...v0.13.9-2026-02-03}&quot;">​</a></h2><h3 id="Added-5" tabindex="-1">Added <a class="header-anchor" href="#Added-5" aria-label="Permalink to &quot;Added {#Added-5}&quot;">​</a></h3><ul><li><p><code>LocalPreferences.toml</code> file to ensure <code>TensorOperations</code> properly precompiles on testing infrastructure</p></li><li><p><code>GeometryStyle</code> and <code>OperatorStyle</code> traits for dispatching on finite/infinite geometry and operator types (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/352" target="_blank" rel="noreferrer">#352</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/354" target="_blank" rel="noreferrer">#354</a>)</p></li><li><p><code>Base.isfinite</code> methods for MPS types (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/347" target="_blank" rel="noreferrer">#347</a>)</p></li><li><p>Bose-Hubbard example (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/342" target="_blank" rel="noreferrer">#342</a>)</p></li><li><p>WindowMPS example update (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/350" target="_blank" rel="noreferrer">#350</a>)</p></li><li><p>Multifusion category compatibility (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/297" target="_blank" rel="noreferrer">#297</a>)</p></li></ul><h3 id="Fixed-5" tabindex="-1">Fixed <a class="header-anchor" href="#Fixed-5" aria-label="Permalink to &quot;Fixed {#Fixed-5}&quot;">​</a></h3><ul><li><p>Dynamic tolerances yielded <code>NaN</code> during the initialization stage due to <code>1 / sqrt(iter)</code> where <code>iter = 0</code> (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/335" target="_blank" rel="noreferrer">#335</a>)</p></li><li><p><code>InfiniteMPOHamiltonian</code> environments with low bond dimension and high Krylov dimension now are properly clamped (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/335" target="_blank" rel="noreferrer">#335</a>)</p></li><li><p>Logical operator precedence in <code>getproperty</code> function (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/346" target="_blank" rel="noreferrer">#346</a>)</p></li><li><p>Typo in <code>VUMPSSvdCut</code> (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/361" target="_blank" rel="noreferrer">#361</a>)</p></li><li><p>Typo in time formatting for logs (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/336" target="_blank" rel="noreferrer">#336</a>)</p></li><li><p>Domain/codomain of <code>MPODerivativeOperator</code> (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/370" target="_blank" rel="noreferrer">#370</a>)</p></li><li><p>In-place operations handled more carefully (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/337" target="_blank" rel="noreferrer">#337</a>)</p></li><li><p>Orthogonalization algorithms now use correct methods (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/373" target="_blank" rel="noreferrer">#373</a>)</p></li></ul><h3 id="Changed-5" tabindex="-1">Changed <a class="header-anchor" href="#Changed-5" aria-label="Permalink to &quot;Changed {#Changed-5}&quot;">​</a></h3><ul><li><p>The <code>changebonds(state, ::RandExpand)</code> algorithm now no longer has to perform a truncated SVD to obtain the desired spaces, and instead sample the space directly and then generates a random isometry. This should be slightly more performant, but otherwise equivalent (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/335" target="_blank" rel="noreferrer">#335</a>)</p></li><li><p><code>IDMRG</code> refactored to follow the <code>IterativeSolver</code> interface and share code between <code>IDMRG</code> and <code>IDMRG2</code> (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/348" target="_blank" rel="noreferrer">#348</a>)</p></li><li><p>Bumped compatibility for TensorKit 0.16 and MatrixAlgebraKit 0.6 (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/365" target="_blank" rel="noreferrer">#365</a>)</p></li><li><p>Removed <code>_left_orth</code> and <code>_right_orth</code> workarounds in favor of new orthogonalization methods</p></li><li><p>Reduced allocation while computing Galerkin error (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/366" target="_blank" rel="noreferrer">#366</a>)</p></li><li><p>Updated <code>show</code> methods to reflect new TensorKit printing (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/341" target="_blank" rel="noreferrer">#341</a>)</p></li><li><p>More informative errors for finite MPS (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/367" target="_blank" rel="noreferrer">#367</a>)</p></li><li><p>Minor documentation and docstring improvements (<a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/363" target="_blank" rel="noreferrer">#363</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/372" target="_blank" rel="noreferrer">#372</a>, <a href="https://github.com/QuantumKitHub/MPSKit.jl/pull/371" target="_blank" rel="noreferrer">#371</a>)</p></li></ul><h3 id="Deprecated-3" tabindex="-1">Deprecated <a class="header-anchor" href="#Deprecated-3" aria-label="Permalink to &quot;Deprecated {#Deprecated-3}&quot;">​</a></h3><h3 id="Removed-3" tabindex="-1">Removed <a class="header-anchor" href="#Removed-3" aria-label="Permalink to &quot;Removed {#Removed-3}&quot;">​</a></h3><h2 id="0.13.8https://github.com/QuantumKitHub/MPSKit.jl/releases/tag/v0.13.8-2024-10-31" tabindex="-1"><a href="https://github.com/QuantumKitHub/MPSKit.jl/releases/tag/v0.13.8" target="_blank" rel="noreferrer">0.13.8</a> - 2024-10-31 <a class="header-anchor" href="#0.13.8https://github.com/QuantumKitHub/MPSKit.jl/releases/tag/v0.13.8-2024-10-31" aria-label="Permalink to &quot;[0.13.8](https://github.com/QuantumKitHub/MPSKit.jl/releases/tag/v0.13.8) - 2024-10-31 {#0.13.8https://github.com/QuantumKitHub/MPSKit.jl/releases/tag/v0.13.8-2024-10-31}&quot;">​</a></h2><p>See full history and previous releases on <a href="https://github.com/QuantumKitHub/MPSKit.jl/releases" target="_blank" rel="noreferrer">GitHub</a>.</p>',54)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
